package com.yeyamo_mobile.api.notification_service.application;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.time.Instant;import java.util.*;import org.junit.jupiter.api.Test;import org.mockito.ArgumentCaptor;import com.yeyamo_mobile.api.notification_service.application.port.*;import com.yeyamo_mobile.api.notification_service.domain.*;
class NotificationApplicationServiceTest{@Test void createsInAppAndEmailAccordingToPreferences(){var notifications=mock(NotificationRepositoryPort.class);var preferences=mock(PreferenceRepositoryPort.class);var templates=mock(TemplatePort.class);var deliveries=mock(DeliveryRepositoryPort.class);var devices=mock(DevicePushTokenRepositoryPort.class);UUID event=UUID.randomUUID();when(notifications.exists(event,"u1")).thenReturn(false);when(preferences.find("u1")).thenReturn(Optional.of(new NotificationPreference("u1",true,true,false,"u@test.io",null,"fr",Instant.now())));when(templates.render(anyString(),any(),anyString(),anyMap())).thenReturn(new RenderedTemplate("Titre","Corps"));when(notifications.save(any())).thenAnswer(i->i.getArgument(0));when(deliveries.save(any())).thenAnswer(i->i.getArgument(0));var result=new NotificationApplicationService(notifications,preferences,templates,deliveries,devices).create(new NotificationIntent(event,"user.created","u1","u@test.io",Map.of("userId","u1"),"{}"));assertTrue(result.isPresent());ArgumentCaptor<Delivery>captor=ArgumentCaptor.forClass(Delivery.class);verify(deliveries,times(2)).save(captor.capture());assertEquals(Set.of(NotificationChannel.IN_APP,NotificationChannel.EMAIL),captor.getAllValues().stream().map(Delivery::channel).collect(java.util.stream.Collectors.toSet()));}@Test void duplicateSourceIsIgnored(){var notifications=mock(NotificationRepositoryPort.class);when(notifications.exists(any(),eq("u1"))).thenReturn(true);var service=new NotificationApplicationService(notifications,mock(PreferenceRepositoryPort.class),mock(TemplatePort.class),mock(DeliveryRepositoryPort.class),mock(DevicePushTokenRepositoryPort.class));assertTrue(service.create(new NotificationIntent(UUID.randomUUID(),"user.created","u1",null,Map.of(),"{}")).isEmpty());}@Test void cannotReadAnotherUsersNotification(){var notifications=mock(NotificationRepositoryPort.class);Notification n=new Notification(UUID.randomUUID(),UUID.randomUUID(),"user.created","u2","T","B","{}",Instant.now(),null);when(notifications.findById(n.id())).thenReturn(Optional.of(n));var service=new NotificationApplicationService(notifications,mock(PreferenceRepositoryPort.class),mock(TemplatePort.class),mock(DeliveryRepositoryPort.class),mock(DevicePushTokenRepositoryPort.class));assertThrows(NoSuchElementException.class,()->service.read("u1",n.id()));}}
